/* RESPONSIVE: SMALL PHONES */
@media (max-width: 480px) {
  :root {
    --gutter: 19px;
    --section-space: 60px;
  }

  body {
    font-size: 15px;
  }

  h2 {
    font-size: 2.35rem;
  }

  .brand-description {
    max-width: 155px;
    line-height: 1.4;
  }

  .hero-content {
    padding-top: 58px;
    padding-bottom: 45px;
  }

  .hero h1 {
    font-size: clamp(2.65rem, 12vw, 3.55rem);
  }

  .hero-actions {
    width: 100%;
    align-items: stretch;
    flex-direction: column;
  }

  .hero-actions .button {
    width: 100%;
  }

  .hero-credentials {
    align-items: flex-start;
    flex-direction: column;
  }

  .principles {
    grid-template-columns: 1fr;
  }

  .roof-signs {
    grid-template-columns: 1fr;
    gap: 12px;
  }

  .process-steps {
    grid-template-columns: 1fr;
    gap: 30px;
  }

  .process-step {
    padding-left: 20px;
    padding-top: 0;
  }

  .process-step::before {
    top: 8px;
  }

  .process-step .step-number {
    margin-bottom: 10px;
  }

  .process-step p {
    max-width: none;
  }

  .projects-grid {
    grid-template-columns: 1fr;
  }

  .project-image img,
  .project--featured .project-image img {
    aspect-ratio: 16 / 10;
  }

  .contact-form {
    grid-template-columns: 1fr;
    gap: 16px;
  }

  .form-field--full,
  .form-submit,
  .form-note {
    grid-column: auto;
  }

  .footer-actions {
    width: 100%;
    align-items: stretch;
    flex-direction: column;
  }

  .footer-actions .button {
    width: 100%;
  }

  .footer-brand {
    align-items: flex-start;
  }

  .footer-brand strong {
    font-size: 1.1rem;
  }
}

/* REDUCED MOTION */
@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .01ms !important;
  }
}
